  ('00000000-0000-4000-8000-001000000001', 'Rise and Reform', 'rise-and-reform', 'Small-group Reformer Pilates.', 'Small-group Reformer Pilates classes in Leamington Spa, Rugby, Stratford-upon-Avon and Kenilworth.', 'Reformer Pilates', array['Small-group Reformer Pilates classes']::text[], null, '/images/partners/rise-and-reform-logo.png', 'light', '/images/partners/rise-and-reform-cover.webp', null, null, false, false, 'https://risereformpilates.com/', '{}'::jsonb, 'Leamington Spa, Rugby, Stratford-upon-Avon & Kenilworth', null, 'active', true, false),
  ('00000000-0000-4000-8000-001000000002', 'The Leamington Dog Field', 'the-leamington-dog-field', 'A bookable dog field at Squab Hall.', 'The Leamington Dog Field is based at Squab Hall. Sessions are booked online.', 'Dog field', array['Bookable field sessions']::text[], null, '/images/partners/leamington-dog-field-logo.png', 'light', null, null, null, false, false, 'https://leamingtonspadogfield.simplybook.it/', '{}'::jsonb, 'Squab Hall, Leamington Spa', null, 'active', true, false),
  ('00000000-0000-4000-8000-001000000003', 'Proper Golfing', 'proper-golfing', 'The Timeless Golf Swing, for golfers over 45.', 'Proper Golfing teaches the Timeless Golf Swing — effortless, repeatable golf coaching for golfers over 45 with PGA Professional Julian Mellor.', 'Golf coaching', array['Golf lessons for golfers over 45']::text[], null, '/images/partners/proper-golfing-logo.svg', 'light', '/images/partners/proper-golfing-studio.webp', null, null, false, false, 'https://propergolfing.com/', '{}'::jsonb, null, null, 'active', true, false),
  ('00000000-0000-4000-8000-001000000004', 'Swim in a Tin', 'swim-in-a-tin', 'Swim at your own pace in a private space.', 'Swim at your own pace in a safe, private, personalised space to swim, train or learn — with or without qualified, supportive coaches.', 'Private swimming', array['Private swim sessions', 'Coached swimming']::text[], null, '/images/partners/swim-in-a-tin-logo.png', 'light', '/images/partners/swim-in-a-tin-containers.webp', null, null, false, false, 'https://www.swiminatin.com/', '{}'::jsonb, null, null, 'active', true, false),
  ('00000000-0000-4000-8000-001000000005', 'The Hide Cafe', 'the-hide-cafe', 'The café at Squab Hall Farm.', 'The Hide is the café at Squab Hall Farm.', 'Café', array['Coffee and drinks', 'Food']::text[], null, '/images/partners/the-hide-cafe-logo.png', 'light', '/images/partners/the-hide-cafe-cover.webp', null, null, false, false, 'https://squabhallfarm.co.uk/services/cafe/', '{}'::jsonb, 'Squab Hall Farm', null, 'active', true, false),
  ('00000000-0000-4000-8000-001000000006', 'Project 23', 'project-23', 'Personal training in a private gym.', 'Personal training and small-group coaching at Project 23’s private gym in Leamington Spa, near Warwick.', 'Personal training', array['Personal training', 'Small-group coaching']::text[], null, '/images/partners/project-23-logo.png', 'dark', '/images/partners/project-23-coaching.webp', null, null, false, false, 'https://project23coaching.co.uk/', '{}'::jsonb, 'Leamington Spa', null, 'active', true, false),
  ('00000000-0000-4000-8000-001000000007', 'AM Joinery', 'am-joinery', 'A joinery workshop based at Squab.', 'AM Joinery runs its joinery workshop from a unit at Squab.', 'Joinery', array['Joinery']::text[], null, null, 'light', '/images/partners/am-joinery-cover.webp', null, null, false, false, null, '{}'::jsonb, null, 'Squab tenant with a joinery workshop on site.', 'active', false, false)
insert into public.offers (id, business_id, title, slug, short_description, full_description, what_you_get, how_to_redeem, image_url, reward_type, reward_value, redemption_method, redemption_url, redemption_code, contact_email, contact_phone, terms, start_date, expiry_date, status, featured, is_demo, created_at, published_at) values
  ('00000000-0000-4000-8000-002000000001', '00000000-0000-4000-8000-001000000001', 'Free first pilates session', 'rise-and-reform-risefree', 'Free first pilates session at Rise and Reform, exclusively for Squab customers.', 'Small-group Reformer Pilates classes in Leamington Spa, Rugby, Stratford-upon-Avon and Kenilworth. Squab customers get free first pilates session with the code below.', '{}'::text[], 'Show your code (or the QR code) at Rise and Reform, or quote it when you book with them.', null, 'introductory', 'Free first session', 'code', 'https://risereformpilates.com/', 'RISEFREE', null, null, '', null, null, 'published', true, false, '2026-09-18T09:00:00Z', '2026-09-18T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000002', '00000000-0000-4000-8000-001000000002', '20% off your first booking', 'the-leamington-dog-field-leamdog20', '20% off your first booking at The Leamington Dog Field, exclusively for Squab customers.', 'The Leamington Dog Field is based at Squab Hall. Sessions are booked online. Squab customers get 20% off your first booking with the code below.', '{}'::text[], 'Show your code (or the QR code) at The Leamington Dog Field, or quote it when you book with them.', null, 'percentage', '20% off', 'code', 'https://leamingtonspadogfield.simplybook.it/', 'LEAMDOG20', null, null, '', null, null, 'published', true, false, '2026-09-18T09:00:00Z', '2026-09-18T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000003', '00000000-0000-4000-8000-001000000003', '25% off your first lesson', 'proper-golfing-proper25', '25% off your first lesson at Proper Golfing, exclusively for Squab customers.', 'Proper Golfing teaches the Timeless Golf Swing — effortless, repeatable golf coaching for golfers over 45 with PGA Professional Julian Mellor. Squab customers get 25% off your first lesson with the code below.', '{}'::text[], 'Show your code (or the QR code) at Proper Golfing, or quote it when you book with them.', null, 'percentage', '25% off', 'code', 'https://propergolfing.com/', 'PROPER25', null, null, '', null, null, 'published', true, false, '2026-09-18T09:00:00Z', '2026-09-18T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000004', '00000000-0000-4000-8000-001000000004', '15% off sessions', 'swim-in-a-tin-swimtin15', '15% off sessions at Swim in a Tin, exclusively for Squab customers.', 'Swim at your own pace in a safe, private, personalised space to swim, train or learn — with or without qualified, supportive coaches. Squab customers get 15% off sessions with the code below.', '{}'::text[], 'Show your code (or the QR code) at Swim in a Tin, or quote it when you book with them.', null, 'percentage', '15% off', 'code', 'https://www.swiminatin.com/', 'SWIMTIN15', null, null, '', null, null, 'published', true, false, '2026-09-18T09:00:00Z', '2026-09-18T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000005', '00000000-0000-4000-8000-001000000005', '20% off any drink', 'the-hide-cafe-hide20', '20% off any drink at The Hide Cafe, exclusively for Squab customers.', 'The Hide is the café at Squab Hall Farm. Squab customers get 20% off any drink with the code below.', '{}'::text[], 'Show your code (or the QR code) at The Hide Cafe, or quote it when you book with them.', null, 'percentage', '20% off', 'code', 'https://squabhallfarm.co.uk/services/cafe/', 'HIDE20', null, null, '', null, null, 'published', true, false, '2026-09-18T09:00:00Z', '2026-09-18T09:00:00Z'),
  ('00000000-0000-4000-8000-002000000006', '00000000-0000-4000-8000-001000000006', '30 minute personal training consultation', 'project-23-p23train30', '30 minute personal training consultation at Project 23, exclusively for Squab customers.', 'Personal training and small-group coaching at Project 23’s private gym in Leamington Spa, near Warwick. Squab customers get 30 minute personal training consultation with the code below.', '{}'::text[], 'Show your code (or the QR code) at Project 23, or quote it when you book with them.', null, 'complimentary', 'Free consultation', 'code', 'https://project23coaching.co.uk/', 'P23TRAIN30', null, null, '', null, null, 'published', true, false, '2026-09-18T09:00:00Z', '2026-09-18T09:00:00Z')
insert into public.stories (id, title, slug, standfirst, body, hero_image, hero_image_alt, author_name, category_id, format, related_business_id, status, featured, is_demo, published_at) values
  ('00000000-0000-4000-8000-003000000005', 'Padel is coming to Squab', 'padel-is-coming-to-squab', 'Plans for three indoor padel courts, changing rooms and a café at Squab Hall Farm have been approved. Watch this space.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Big news: padel is coming to Squab.","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Warwick District Council’s planning committee has approved plans for a new indoor padel centre at Squab Hall Farm, off Harbury Lane near Leamington Spa. Councillors backed the scheme for the local jobs and the community health and sport it will bring, and Bishop’s Tachbrook Parish Council supported it too."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What’s planned"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Three indoor padel courts","marks":[{"type":"bold"}]},{"type":"text","text":" — play whatever the weather"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changing rooms"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A café"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open 7am to 11pm, seven days a week"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Around six new local jobs"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The courts will be created inside an existing building on the site, right alongside the businesses, tenants and customers who already make Squab their base."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What is padel?"}]},{"type":"paragraph","content":[{"type":"text","text":"Padel is one of the fastest-growing sports in the UK. It’s played in doubles on an enclosed court, a little like a mix of tennis and squash: easy to pick up, very sociable and great fun at any level."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Watch this space"}]},{"type":"paragraph","content":[{"type":"text","text":"We’ll share opening dates, booking details and first-look photos here on Squab Connect as soon as we have them."}]},{"type":"paragraph","content":[{"type":"text","text":"Read the local coverage from "},{"type":"text","text":"Warwick Nub News","marks":[{"type":"link","attrs":{"href":"https://warwick.nub.news/news/local-news/padel-courts-to-be-built-against-officers-recommendation-311625"}}]},{"type":"text","text":" and "},{"type":"text","text":"Insider Media","marks":[{"type":"link","attrs":{"href":"https://www.insidermedia.com/news/midlands/warwickshire-padel-centre-green-lit-contrary-to-officers-recommendation"}}]},{"type":"text","text":"."}]},{"type":"ctaButton","attrs":{"label":"See what’s on at Squab","href":"/events"}}]}'::jsonb, '/images/squab/aerial.webp', 'Aerial view of the Squab site', 'The Squab Connect team', '00000000-0000-4000-8000-000300000003', 'standard', null, 'published', true, true, '2026-11-07T10:00:00Z'),
  ('00000000-0000-4000-8000-003000000004', 'Meet us at The Midlands Business Network Expo 2026', 'midlands-business-network-expo-2026', 'Squab is exhibiting in Stratford-upon-Avon on 27 November. Grow, learn, connect — and come and say hello.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We’re exhibiting at "},{"type":"text","text":"The Midlands Business Network Expo 2026","marks":[{"type":"bold"}]},{"type":"text","text":" — a day of connections for businesses from across the region."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When:","marks":[{"type":"bold"}]},{"type":"text","text":" Friday 27 November 2026"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where:","marks":[{"type":"bold"}]},{"type":"text","text":" Stratford-upon-Avon"}]}]}]},{"type":"image","attrs":{"alt":"We''re exhibiting at The Midlands Business Network Expo 2026 — grow, learn, connect","src":"/images/events/expo-2026.webp"}},{"type":"paragraph","content":[{"type":"text","text":"If you’re going, come and find the Squab team. We’d love to talk about storage, workspace and the businesses that make up the Squab community."}]},{"type":"ctaButton","attrs":{"label":"Event details","href":"/events/midlands-business-network-expo-2026"}}]}'::jsonb, '/images/events/expo-2026-wide.webp', 'We''re exhibiting: The Midlands Business Network Expo 2026, 27 November, Stratford-upon-Avon', 'The Squab Connect team', '00000000-0000-4000-8000-000300000004', 'standard', null, 'published', false, true, '2026-11-07T08:00:00Z'),
  ('00000000-0000-4000-8000-003000000001', 'Meet the businesses behind Squab Perks', 'meet-the-businesses-behind-squab-perks', 'Pilates, golf, swimming, coffee, a dog field and a private gym — here’s who’s offering something extra to Squab customers.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Squab Perks brings together offers from businesses in and around the Squab community. Here’s a quick introduction to the first six."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rise and Reform"}]},{"type":"paragraph","content":[{"type":"text","text":"Small-group Reformer Pilates across Leamington Spa, Rugby, Stratford-upon-Avon and Kenilworth. Squab customers get "},{"type":"text","text":"their first session free","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Leamington Dog Field"}]},{"type":"paragraph","content":[{"type":"text","text":"A bookable dog field at Squab Hall — "},{"type":"text","text":"20% off your first booking","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Proper Golfing"}]},{"type":"paragraph","content":[{"type":"text","text":"Golf coaching for golfers over 45 with PGA Professional Julian Mellor — "},{"type":"text","text":"25% off your first lesson","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Swim in a Tin"}]},{"type":"paragraph","content":[{"type":"text","text":"Private, personalised swimming, with or without a coach — "},{"type":"text","text":"15% off sessions","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Hide Cafe"}]},{"type":"paragraph","content":[{"type":"text","text":"The café at Squab Hall Farm — "},{"type":"text","text":"20% off any drink","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Project 23"}]},{"type":"paragraph","content":[{"type":"text","text":"Personal training at a private gym in Leamington Spa — "},{"type":"text","text":"a free 30-minute consultation","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"ctaButton","attrs":{"label":"See all Squab Perks","href":"/perks"}}]}'::jsonb, '/images/partners/the-hide-cafe-cover.webp', 'Inside The Hide café at Squab Hall Farm', 'The Squab Connect team', '00000000-0000-4000-8000-000300000001', 'standard', null, 'published', false, true, '2026-11-03T08:00:00Z'),
  ('00000000-0000-4000-8000-003000000002', 'Introducing Squab Connect', 'introducing-squab-connect', 'One place for offers, local businesses, news and events from across the Squab community.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sample copy — to be replaced with Squab’s own announcement.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Squab Connect is a new home for the Squab community. Browse exclusive perks from local businesses, find out who’s around you and keep up with news and events."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What you can do"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use Squab Perks","marks":[{"type":"bold"}]},{"type":"text","text":" — show a code at the business or use it when you book."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Discover local businesses","marks":[{"type":"bold"}]},{"type":"text","text":" in the directory."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Come along to an event","marks":[{"type":"bold"}]},{"type":"text","text":" and meet people face to face."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Run a business and want to offer something to Squab customers? "},{"type":"text","text":"Find out how to take part","marks":[{"type":"link","attrs":{"href":"/about#businesses"}}]},{"type":"text","text":"."}]},{"type":"ctaButton","attrs":{"label":"Explore Squab Perks","href":"/perks"}}]}'::jsonb, '/images/partners/the-hide-cafe-gathering.webp', 'People chatting over coffee at The Hide café', 'The Squab Connect team', '00000000-0000-4000-8000-000300000003', 'standard', null, 'published', false, true, '2026-11-01T08:00:00Z'),
  ('00000000-0000-4000-8000-003000000003', 'Squab Networking is back', 'squab-networking-is-back', 'Friendly local connections for growing businesses — with guest speaker Tracey Barnbrook.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Squab Networking is back: a relaxed morning of friendly local connections for growing businesses."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When:","marks":[{"type":"bold"}]},{"type":"text","text":" Tuesday 29 September, 10:00–12:30"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guest speaker:","marks":[{"type":"bold"}]},{"type":"text","text":" Tracey Barnbrook"}]}]}]},{"type":"image","attrs":{"alt":"Squab Networking is back — Tuesday 29 September, 10:00–12:30, with guest speaker Tracey Barnbrook","src":"/images/squab/networking-is-back.webp"}},{"type":"ctaButton","attrs":{"label":"See upcoming events","href":"/events"}}]}'::jsonb, '/images/squab/networking-room.webp', 'Business owners chatting over coffee at a Squab networking morning', 'The Squab Connect team', '00000000-0000-4000-8000-000300000004', 'standard', null, 'published', false, true, '2026-09-15T08:00:00Z')
insert into public.events (id, title, slug, summary, description, what_to_expect, who_should_attend, image_url, start_datetime, end_datetime, time_tbc, venue, address, registration_url, contact_email, capacity, fully_booked, status, featured, is_demo) values
  ('00000000-0000-4000-8000-004000000004', 'The Midlands Business Network Expo 2026', 'midlands-business-network-expo-2026', 'Squab is exhibiting at The Midlands Business Network Expo in Stratford-upon-Avon. Come and say hello.', 'Squab is exhibiting at The Midlands Business Network Expo 2026 in Stratford-upon-Avon on 27 November.
insert into public.site_settings (key, value) values
  ('homepage', '{"hero":{"eyebrow":"Welcome to Squab Connect","headline":"Good things happen when we connect.","highlight":"we connect.","subheading":"Discover exclusive offers, meet the businesses around you and stay up to date with everything happening across the Squab community.","primaryCta":{"label":"Explore Squab Perks","href":"/perks"},"secondaryCta":{"label":"Discover our community","href":"/businesses"},"imageUrl":"/images/squab/aerial.webp"},"community":{"headline":"Part of the Squab community? Make yourself known.","body":"Whether you have a business to promote, an offer to share or simply want to meet the people around you, Squab Connect is the place to start.","cta":{"label":"Find out more","href":"/about"}}}'::jsonb)
